import urllib.request, json
for path in [
    'https://api.render.com/v1/redis/redis-d7t9k7tqo5us73ftosj0' if False else 'https://api.render.com/v1/services?limit=50',
    'https://api.render.com/v1/services/srv-d7t9ivreo5us73ftose0/events?limit=20',
]:
    print('---', path)
    try:
        req = urllib.request.Request(path, headers={'Authorization': 'Bearer rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs', 'Accept': 'application/json'})
        resp = urllib.request.urlopen(req, timeout=10)
        print('status', resp.status)
        text = resp.read().decode()
        data = json.loads(text)
        if isinstance(data, list):
            for item in data[:10]:
                s = item.get('service', item)
                print(s.get('type'), s.get('name'), s.get('id'), s.get('status', '?'))
        else:
            print(json.dumps(data, indent=2, default=str)[:2000])
    except Exception as e:
        print('error', type(e).__name__, str(e)[:200])
""}

