import { readFileSync, statSync, existsSync } from 'fs';

const SUPABASE_URL = 'https://kvclcdjmjghndxsngfzb.supabase.co';
const SUPABASE_ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imt2Y2xjZGptamdobmR4c25nZnpiIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzMxOTQwMjcsImV4cCI6MjA4ODc3MDAyN30.OLDwa21VHQNs151AD-8k--_HigQ2d-N7yJfFn5UeNPk';
const API_BASE_URL = 'https://api.ivxholding.com';
const OWNER_EMAIL = 'iperez4242@gmail.com';
const PASSWORD = process.env.IVX_OWNER_PASSWORD || '';
const APK_PATH = '/tmp/ivx-holdings-1.10.13-owner.apk';
const S3_KEY = 'apk/ivx-holdings-1.10.13-owner.apk';

function log(msg) { console.log(`[Upload APK] ${msg}`); }
function err(msg) { console.error(`[Upload APK] ERROR: ${msg}`); }

async function signInWithPassword() {
  if (!PASSWORD) throw new Error('IVX_OWNER_PASSWORD env var not set');
  log('Signing in with Supabase password...');
  const url = `${SUPABASE_URL}/auth/v1/token?grant_type=password`;
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      'apikey': SUPABASE_ANON_KEY,
      'Authorization': `Bearer ${SUPABASE_ANON_KEY}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ email: OWNER_EMAIL, password: PASSWORD }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || !data.access_token) {
    throw new Error(`Sign-in failed (${res.status}): ${data.message || data.error || 'no access_token'}`);
  }
  log(`JWT obtained (${data.access_token.length} chars).`);
  return data.access_token;
}

async function getPresignedUploadUrl(jwt) {
  log(`Requesting presigned upload URL for key: ${S3_KEY}`);
  const res = await fetch(`${API_BASE_URL}/api/ivx/apk/presign-upload`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${jwt}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ key: S3_KEY, confirm: true, confirmText: 'CONFIRM_IVX_APK_UPLOAD' }),
  });
  const data = await res.json().catch(() => ({}));
  if (!data.uploadUrl) {
    throw new Error(`Presign failed (${res.status}): ${data.error || data.detail || JSON.stringify(data).slice(0, 200)}`);
  }
  log(`Presigned URL minted.`);
  return { uploadUrl: data.uploadUrl, publicUrl: data.publicUrl };
}

async function uploadToPresignedUrl(uploadUrl, apkPath) {
  const fileData = readFileSync(apkPath);
  const fileSize = statSync(apkPath).size;
  log(`Uploading ${(fileSize / (1024 * 1024)).toFixed(1)} MB to S3...`);
  const res = await fetch(uploadUrl, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/vnd.android.package-archive' },
    body: fileData,
  });
  if (!res.ok) {
    const body = await res.text().catch(() => '');
    throw new Error(`S3 PUT failed (${res.status}): ${body.slice(0, 300)}`);
  }
  log(`Upload complete (${fileSize} bytes, HTTP ${res.status}).`);
}

async function verifyPublicUrl(publicUrl) {
  log(`Verifying public URL: ${publicUrl}`);
  const res = await fetch(publicUrl, { method: 'HEAD' });
  if (res.status !== 200) {
    throw new Error(`Verification failed: HTTP ${res.status}`);
  }
  const contentType = res.headers.get('content-type') || '';
  const contentLength = res.headers.get('content-length') || '0';
  log(`Verified: HTTP ${res.status}, ${contentType}, ${contentLength} bytes.`);
  return { status: res.status, contentType, contentLength };
}

async function main() {
  if (!existsSync(APK_PATH)) throw new Error(`APK not found: ${APK_PATH}`);
