const API_BASE_URL = 'https://api.ivxholding.com';

async function testChat(message, label) {
  console.log(`\n--- ${label} ---`);
  const start = performance.now();
  const res = await fetch(`${API_BASE_URL}/api/public/chat`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      message,
      threadId: null,
      source: 'chatgpt',
      stream: true,
    }),
  });
  const firstByte = performance.now();
  const reader = res.body?.getReader();
  if (!reader) {
    console.log('No response body');
    return;
  }
  let fullText = '';
  const decoder = new TextDecoder();
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    const chunk = decoder.decode(value, { stream: true });
    fullText += chunk;
    if (fullText.length < 300) process.stdout.write(chunk);
  }
  const end = performance.now();
  console.log(`\nStatus: ${res.status}, TTFT: ${(firstByte - start).toFixed(0)}ms, total: ${(end - start).toFixed(0)}ms, chars: ${fullText.length}`);
  return fullText;
}

await testChat('Hola, ¿cómo estás? Responde en español.', 'Spanish chat');
await testChat('What is the capital of France?', 'English chat');

