const API_KEY = process.env.RENDER_API_KEY ?? 'rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs';
const SERVICE_ID = process.env.RENDER_SERVICE_ID ?? 'srv-d7t9ivreo5us73ftose0';
const OWNER_PASSWORD = 'X146corp@1x146corp$$1x146corp$$1x146corp$$';
const VAR_NAME = 'IVX_OWNER_PASSWORD';

async function renderFetch(path, init = {}) {
  const url = `https://api.render.com/v1${path}`;
  const res = await fetch(url, {
    ...init,
    headers: {
      Accept: 'application/json',
      Authorization: `Bearer ${API_KEY}`,
      'Content-Type': 'application/json',
      ...(init.headers || {}),
    },
  });
  const text = await res.text();
  let j = {};
  try { j = JSON.parse(text); } catch {}
  return { ok: res.ok, status: res.status, payload: j, text };
}

async function listEnvVars() {
  const r = await renderFetch(`/services/${SERVICE_ID}/env-vars`);
  if (!r.ok) {
    console.log(JSON.stringify({ error: 'list failed', status: r.status, text: r.text.slice(0, 200) }, null, 2));
    process.exit(1);
  }
  return Array.isArray(r.payload) ? r.payload : [];
}

async function upsertEnvVar(name, value) {
  const existing = await listEnvVars();
  const match = existing.find((item) => item.envVar?.key === name || item.key === name);
  const id = match?.envVar?.id || match?.id;
  const body = JSON.stringify({ key: name, value });
  if (id) {
    const r = await renderFetch(`/services/${SERVICE_ID}/env-vars/${id}`, { method: 'PUT', body });
    console.log(`Updated ${name}: ${r.ok ? 'OK' : `FAILED ${r.status}`}`);
    return r.ok;
  }
  const r = await renderFetch(`/services/${SERVICE_ID}/env-vars`, { method: 'POST', body });
  console.log(`Created ${name}: ${r.ok ? 'OK' : `FAILED ${r.status}`}`);
  return r.ok;
}

const ok = await upsertEnvVar(VAR_NAME, OWNER_PASSWORD);
process.exit(ok ? 0 : 1);

