const RENDER_API_KEY = process.env.RENDER_API_KEY ?? 'rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs';
const RENDER_SERVICE_ID = process.env.RENDER_SERVICE_ID ?? 'srv-d7t9ivreo5us73ftose0';
const PROJECT_REF = 'kvclcdjmjghndxsngfzb';
const OWNER_EMAIL = 'iperez4242@gmail.com';
const OWNER_PASSWORD = 'X146corp@1x146corp$$1x146corp$$1x146corp$$';

async function renderFetch(path, init = {}) {
  const res = await fetch(`https://api.render.com/v1${path}`, {
    ...init,
    headers: {
      Accept: 'application/json',
      Authorization: `Bearer ${RENDER_API_KEY}`,
      'Content-Type': 'application/json',
      ...(init.headers || {}),
    },
  });
  const text = await res.text();
  let j = {};
  try { j = JSON.parse(text); } catch {}
  return { ok: res.ok, status: res.status, payload: j, text };
}

async function getSupabaseAccessToken() {
  const r = await renderFetch(`/services/${RENDER_SERVICE_ID}/env-vars`);
  if (!r.ok) throw new Error(`Failed to list Render env vars: ${r.status}`);
  const vars = Array.isArray(r.payload) ? r.payload.map((e) => e.envVar) : [];
  const match = vars.find((v) => v.key === 'SUPABASE_ACCESS_TOKEN');
  if (!match || !match.value) throw new Error('SUPABASE_ACCESS_TOKEN not found in Render env vars');
  return match.value;
}

async function createUser() {
  const token = await getSupabaseAccessToken();
  const res = await fetch(`https://api.supabase.com/v1/projects/${PROJECT_REF}/auth/users`, {
