import json, os, re, glob
from collections import defaultdict

HISTORY_DIR = '.rork/history/main'
TARGET_KEYS = [
    'IVX_AI_GATEWAY_KEY', 'AI_GATEWAY_API_KEY', 'IVX_ANTHROPIC_API_KEY', 'IVX_OPENAI_API_KEY',
    'SUPABASE_DB_PASSWORD', 'SUPABASE_DB_URL', 'IVX_AI_SYSTEM_SECRET', 'JWT_SECRET',
    'SUPABASE_ACCESS_TOKEN', 'IVX_INTERNAL_DEPLOY_SECRET', 'IVX_OWNER_TOKEN',
    'IVX_OWNER_REGISTRATION_EMAILS', 'IVX_OWNER_EMAIL', 'IVX_OWNER_RECOVERY_PHONE',
    'GITHUB_TOKEN', 'GITHUB_DEFAULT_BRANCH', 'GITHUB_REPO', 'GITHUB_REPO_URL',
    'RENDER_SERVICE_ID', 'RENDER_API_KEY', 'SUPABASE_SERVICE_ROLE_KEY', 'SUPABASE_SERVICE_KEY',
    'EXPO_PUBLIC_SUPABASE_URL', 'EXPO_PUBLIC_SUPABASE_ANON_KEY', 'SUPABASE_URL',
    'IVX_FORCE_DEPLOY_SHA', 'IVX_INTERNAL_WORKER_ID', 'IVX_SES_FROM_EMAIL', 'IVX_FORCE_REDEPLOY',
    'EXPO_PUBLIC_IVX_API', 'PRODUCTION_BASE_URL',
]

# Gather all envVar entries from history files, keeping the latest per key
latest = {}

files = sorted(glob.glob(os.path.join(HISTORY_DIR, '*.json')), key=os.path.getmtime, reverse=True)
for path in files:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        continue

    # Recursively search for envVar structures
    def scan(obj):
        if isinstance(obj, dict):
            if 'envVar' in obj and isinstance(obj['envVar'], dict):
                ev = obj['envVar']
                key = ev.get('key')
                val = ev.get('value')
                if key and val and key in TARGET_KEYS and key not in latest:
                    latest[key] = val
            for v in obj.values():
                scan(v)
        elif isinstance(obj, list):
            for v in obj:
                scan(v)

    scan(data)

# Also look for patterns like "KEY=value" in stdout strings
for path in files:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        continue

    def scan_text(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                scan_text(v)
        elif isinstance(obj, list):
            for v in obj:
                scan_text(v)
        elif isinstance(obj, str):
            for key in TARGET_KEYS:
                if key in latest:
                    continue
                # Look for "key":"value" or key=value
                m = re.search(rf'"{re.escape(key)}"\s*:\\s*"([^"]+)"', obj)
                if m:
                    latest[key] = m.group(1)
                    continue
                m = re.search(rf'{re.escape(key)}=([^\s\\n]+)', obj)
                if m:
                    latest[key] = m.group(1)

    scan_text(data)

for key in TARGET_KEYS:
    val = latest.get(key)
    if val:
        print(f'{key}={len(val)}')
    else:
        print(f'{key}=MISSING')

