const RENDER_API_KEY = 'rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs';
const SERVICE_ID = 'srv-d7t9ivreo5us73ftose0';
const API_BASE = 'https://api.render.com/v1';

async function renderFetch(path) {
  const res = await fetch(`${API_BASE}${path}`, {
    headers: { Authorization: `Bearer ${RENDER_API_KEY}`, Accept: 'application/json' },
  });
  const text = await res.text();
  let j = null;
  try { j = JSON.parse(text); } catch {}
  return { ok: res.ok, status: res.status, body: j, text };
}

async function healthFetch() {
  const res = await fetch('https://api.ivxholding.com/health', { headers: { Accept: 'application/json' } });
  const text = await res.text();
  let j = null;
  try { j = JSON.parse(text); } catch {}
  return { ok: res.ok, status: res.status, body: j, text };
}

async function versionFetch() {
  const res = await fetch('https://api.ivxholding.com/version', { headers: { Accept: 'application/json' } });
  const text = await res.text();
  let j = null;
  try { j = JSON.parse(text); } catch {}
  return { ok: res.ok, status: res.status, body: j, text };
}

async function chatFetch() {
  const res = await fetch('https://api.ivxholding.com/api/public/chat', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify({ sessionId: 'probe-' + Date.now(), message: 'hi' }),
  });
  const text = await res.text();
  let j = null;
  try { j = JSON.parse(text); } catch {}
  return { ok: res.ok, status: res.status, body: j, text };
}

const [deploys, envVars, health, version, chat] = await Promise.all([
  renderFetch(`/services/${SERVICE_ID}/deploys?limit=5`),
  renderFetch(`/services/${SERVICE_ID}/env-vars`),
  healthFetch(),
  versionFetch(),
  chatFetch(),
]);

console.log('=== RENDER DEPLOYS (last 5) ===');
const deployList = Array.isArray(deploys.body) ? deploys.body : [];
for (const d of deployList.slice(0, 5)) {
  const dep = d.deploy || d;
  console.log(`${dep.id}: ${dep.commit?.slice(0, 12) || '?'} ${dep.status} ${dep.createdAt || ''}`);
  if (dep.status === 'live') {
    console.log(`  finishedAt=${dep.finishedAt || ''} commit=${dep.commit?.slice(0, 12) || '?'}`);
  }
}

console.log('\n=== RENDER ENV VARS ===');
const envList = Array.isArray(envVars.body) ? envVars.body : [];
console.log(`count=${envList.length}`);
for (const e of envList) {
  const ev = e.envVar || e;
  const val = ev.value || '';
  console.log(`${ev.key}: ${val.length > 0 ? 'present len=' + val.length : 'EMPTY'}`);
}

console.log('\n=== BACKEND HEALTH ===');
console.log(`status=${health.status} ok=${health.ok}`);
if (health.body) {
  console.log(JSON.stringify({
    status: health.body.status,
    databaseConfigured: health.body.databaseConfigured,
    aiOk: health.body.ai?.ok,
    seniorDevEnabled: health.body.seniorDeveloper?.enabled,
    seniorDevBlockers: health.body.seniorDeveloper?.blockers?.length,
    version: health.body.version,
  }, null, 2));
}

console.log('\n=== BACKEND VERSION ===');
console.log(`status=${version.status} body=${JSON.stringify(version.body)}`);

console.log('\n=== PUBLIC CHAT ===');
console.log(`status=${chat.status} body=${chat.text.slice(0, 300)}`);

