import json, os, glob, re
from collections import defaultdict

HISTORY_DIR = '.rork/history/main'

# Collect all envVar entries from history files, keeping the latest per key by createdAt
latest = {}
latest_time = {}

files = glob.glob(os.path.join(HISTORY_DIR, '*.json'))
for path in files:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        continue

    # Get file timestamp from path if possible, fallback to max createdAt in file
    file_ts = os.path.getmtime(path)
    max_ts = file_ts
    if isinstance(data, list):
        for item in data:
            if isinstance(item, dict) and 'createdAt' in item:
                max_ts = max(max_ts, item.get('createdAt', 0) / 1000.0)

    def scan(obj, ts):
        if isinstance(obj, dict):
            if 'envVar' in obj and isinstance(obj['envVar'], dict):
                ev = obj['envVar']
                key = ev.get('key')
                val = ev.get('value')
                if key and val:
                    if key not in latest or ts > latest_time.get(key, 0):
                        latest[key] = val
                        latest_time[key] = ts
            for v in obj.values():
                scan(v, ts)
        elif isinstance(obj, list):
            for v in obj:
                scan(v, ts)

    scan(data, max_ts)

# Also look for "key":"value" patterns in stdout strings where key is a known env var name
KNOWN_KEYS = set(latest.keys()) | {
    'JWT_SECRET', 'APP_SECRET', 'IVX_OWNER_VARIABLES_ENCRYPTION_KEY',
    'IVX_AI_GATEWAY_KEY', 'AI_GATEWAY_API_KEY', 'OPENAI_API_KEY',
    'SUPABASE_SERVICE_ROLE_KEY', 'SUPABASE_SERVICE_KEY', 'SUPABASE_URL',
    'EXPO_PUBLIC_SUPABASE_URL', 'EXPO_PUBLIC_SUPABASE_ANON_KEY',
    'SUPABASE_ACCESS_TOKEN', 'SUPABASE_PUBLISHABLE_KEY',
    'GITHUB_TOKEN', 'GITHUB_REPO_URL', 'GITHUB_DEFAULT_BRANCH', 'GITHUB_REPO',
    'RENDER_API_KEY', 'RENDER_SERVICE_ID', 'IVX_INTERNAL_DEPLOY_SECRET',
    'IVX_INTERNAL_WORKER_ID', 'IVX_AI_SYSTEM_SECRET', 'IVX_OWNER_TOKEN',
    'IVX_OWNER_REGISTRATION_EMAILS', 'IVX_OWNER_EMAIL', 'IVX_OWNER_RECOVERY_PHONE',
    'IVX_OWNER_PASSWORD', 'IVX_SES_FROM_EMAIL', 'EXPO_PUBLIC_IVX_API',
    'PRODUCTION_BASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
    'AWS_REGION', 'S3_BUCKET_NAME', 'CLOUDFRONT_DISTRIBUTION_ID',
}

for path in files:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        continue
    file_ts = os.path.getmtime(path)

    def scan_text(obj, ts):
        if isinstance(obj, dict):
            for v in obj.values():
                scan_text(v, ts)
        elif isinstance(obj, list):
            for v in obj:
                scan_text(v, ts)
        elif isinstance(obj, str):
            for key in KNOWN_KEYS:
                if key in latest:
                    continue
                # Look for "key":"value" in JSON-like strings
                m = re.search(rf'"{re.escape(key)}"\s*:\s*"([^"]+)"', obj)
                if m and len(m.group(1)) > 10:
                    latest[key] = m.group(1)
                    latest_time[key] = ts
                    continue
                # Look for key=value
                m = re.search(rf'{re.escape(key)}=([A-Za-z0-9_+/=:-]+)', obj)
                if m and len(m.group(1)) > 10:
                    latest[key] = m.group(1)
                    latest_time[key] = ts

    scan_text(data, file_ts)

for key in sorted(latest.keys()):
    val = latest[key]
    print(f'{key}={len(val)}')

