import json, os, glob, re
from collections import defaultdict

HISTORY_DIR = '.rork/history/main'

# Collect env vars from JSON strings that look like Render API responses
all_envs = defaultdict(list)

files = sorted(glob.glob(os.path.join(HISTORY_DIR, '*.json')), key=os.path.getmtime, reverse=True)
for path in files:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        continue

    file_ts = os.path.getmtime(path)

    def find_render_responses(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                find_render_responses(v)
        elif isinstance(obj, list):
            for v in obj:
                find_render_responses(v)
        elif isinstance(obj, str):
            # Look for JSON array starting with [{"envVar":
            for m in re.finditer(r'\[\{[^\}]*"envVar"[^\}]*\}[^\]]*\]', obj):
                s = m.group(0)
                # Fix any escaped inner quotes? Render response is already JSON.
                try:
                    arr = json.loads(s)
                except Exception:
                    continue
                if not isinstance(arr, list):
                    continue
                for item in arr:
                    if isinstance(item, dict) and 'envVar' in item:
                        ev = item['envVar']
                        k = ev.get('key')
                        v = ev.get('value')
                        if k and v is not None:
                            all_envs[k].append((v, file_ts))

    find_render_responses(data)

# For each key, pick the most recent value
latest = {}
for k, vals in all_envs.items():
    # Sort by timestamp descending, pick latest
    vals.sort(key=lambda x: x[1], reverse=True)
    latest[k] = vals[0][0]

print(f'Found {len(latest)} unique env var keys from Render API responses in history')
for k in sorted(latest.keys()):
    v = latest[k]
    print(f'{k}={len(v)}')

