import json, os, glob, re
from collections import defaultdict

HISTORY_DIR = '.rork/history/main'

tokens = defaultdict(list)

files = sorted(glob.glob(os.path.join(HISTORY_DIR, '*.json')), key=os.path.getmtime, reverse=True)[:100]
for path in files:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        continue
    for m in re.finditer(r'vck_[A-Za-z0-9_]{55,65}', text):
        token = m.group(0)
        tokens[token].append(path)

for token, paths in sorted(tokens.items(), key=lambda x: -len(x[1])):
    print(f'{token} (len={len(token)})')
    for p in paths[:3]:
        print(f'  {p}')

