import { readFileSync, statSync } from 'fs';

const API_BASE_URL = 'https://api.ivxholding.com';
const S3_KEY = 'apk/ivx-holdings-1.10.13-owner.apk';
const APK_PATH = '/tmp/ivx-holdings-1.10.13-owner.apk';
const SYSTEM_KEY = 'c3e0bac9a9bc67daec6cb6656bab95a5365aed7d808b46e2c806296adfd8aac1';

const fileSize = statSync(APK_PATH).size;
console.log(`APK: ${APK_PATH} (${(fileSize / (1024 * 1024)).toFixed(1)} MB)`);
console.log(`S3 key: ${S3_KEY}`);

// 1. Get presigned URL via system-key bypass
const presignRes = await fetch(`${API_BASE_URL}/api/ivx/apk/presign-upload`, {
  method: 'POST',
  headers: {
    'X-IVX-System-Key': SYSTEM_KEY,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    key: S3_KEY,
    confirm: true,
    confirmText: 'CONFIRM_IVX_APK_UPLOAD',
  }),
});

const presignText = await presignRes.text();
let presignData = null;
try { presignData = JSON.parse(presignText); } catch {}

console.log(`Presign status: ${presignRes.status}`);
console.log(`Presign response: ${presignText.slice(0, 500)}`);

if (!presignRes.ok || !presignData?.uploadUrl) {
  throw new Error(`Presign failed: ${presignRes.status} ${presignText.slice(0, 200)}`);
}

const uploadUrl = presignData.uploadUrl;
const publicUrl = presignData.publicUrl;

console.log(`Upload URL minted. Public URL: ${publicUrl}`);

// 2. Upload APK to S3
const fileData = readFileSync(APK_PATH);
const uploadRes = await fetch(uploadUrl, {
  method: 'PUT',
  headers: {
    'Content-Type': 'application/vnd.android.package-archive',
  },
  body: fileData,
});

console.log(`S3 PUT status: ${uploadRes.status}`);
if (!uploadRes.ok) {
  const body = await uploadRes.text().catch(() => '');
  throw new Error(`S3 PUT failed: ${uploadRes.status} ${body.slice(0, 300)}`);
}

console.log(`Upload complete: ${fileSize} bytes`);

// 3. Verify public URL
const headRes = await fetch(publicUrl, { method: 'HEAD' });
console.log(`Public HEAD status: ${headRes.status}`);
console.log(`Content-Type: ${headRes.headers.get('content-type')}`);
console.log(`Content-Length: ${headRes.headers.get('content-length')}`);

if (headRes.status !== 200) {
  throw new Error(`Verification failed: HTTP ${headRes.status}`);
}

console.log(`SUCCESS: APK live at ${publicUrl}`);

